/**
 * Accept only the HTTPS endpoint generated by this gateway, never arbitrary credential destinations.
 *
 * @param value
 */
export function gatewayUrl(value: string): string {
  if (value.trim() !== value || !/^https:\/\/tlo\.[a-z0-9]{1,63}\.opentunnel\.xyz(?:\/mcp)?\/?$/u.test(value)) {
    throw new Error('Enter the HTTPS OpenTunnel URL printed by tlo-mcp (https://tlo.<id>.opentunnel.xyz/mcp).');
  }

  return new URL('/mcp', value).href;
}

export function gatewayConnection(account: { fields: { url: string; token: string } }) {
  // Validate the destination before creating credential-bearing headers.
  const url = gatewayUrl(account.fields.url);

  if (account.fields.token.length !== 64 || !/^[a-f0-9]{64}$/u.test(account.fields.token)) {
    throw new Error('Enter the 64-character gateway.key value, not an Orbit token or OpenTunnel identity key.');
  }

  return { url, headers: { Authorization: `Bearer ${account.fields.token}` } };
}
